    spell && !spell.offered && spell.toolSeen && now - spell.startedAt >= settings.offerDelaySec * 1e3 && settings.offersEnabled && canOfferOver(routinePhase) && !inCooldown(lastBreakAt, settings.cooldownMin, now)
